import json
import pymysql
from bs4 import BeautifulSoup

def extract_comment_text(elem):
    """提取评论正文，保留表情符号（alt属性）"""
    content_div = elem.find('div', class_='FduGc_lz')
    if not content_div:
        return ''
    parts = []
    for child in content_div.descendants:
        if child.name == 'img' and child.get('class') and 'qz6Hz920' in child.get('class', []):
            alt = child.get('alt', '').strip()
            if alt:
                parts.append(alt)
        elif isinstance(child, str):
            text = child.strip()
            if text:
                parts.append(text)
    return ''.join(parts).strip()


def parse_comments(html_content):
    """
    解析抖音评论HTML，返回树形结构：
    [
        {"A": "一级评论", "b": ["二级评论1", "二级评论2", ...]},
        ...
    ]
    """
    soup = BeautifulSoup(html_content, 'html.parser')
    all_comments = soup.find_all('div', class_='Eh0a5CD4', attrs={'data-e2e': 'comment-item'})
    top_comments = [
        c for c in all_comments
        if not c.find_parent('div', class_='jHIdiiVr replyContainer')
    ]

    result = []
    for top in top_comments:
        level1_text = extract_comment_text(top)
        reply_container = top.find('div', class_='jHIdiiVr replyContainer')
        level2_texts = []
        if reply_container:
            replies = [
                child for child in reply_container.children
                if child.name == 'div' and child.get('data-e2e') == 'comment-item'
            ]
            for reply in replies:
                text2 = extract_comment_text(reply)
                if text2:
                    level2_texts.append(text2)
        result.append({
            "A": level1_text,
            "b": level2_texts
        })
    return result

import json
import pymysql

def insert_tree_to_mysql(tree_data, host='localhost', user='root', password='zqh123123123', database='test_db'):
    """
    将树形数据插入MySQL，每条一级评论占一行，
    A列存一级评论，B列存所有二级评论的JSON数组（如无二级则为空字符串）
    """
    conn = pymysql.connect(host=host, user=user, password=password, database=database, charset='utf8mb4')
    try:
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS `sz_rpa` (
                `A列` text,
                `B列` text
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
        ''')
        sql = "INSERT INTO `sz_rpa` (`A列`, `B列`) VALUES (%s, %s)"
        rows = []
        for item in tree_data:
            # 将二级评论列表转为JSON字符串
            b_json = json.dumps(item["b"], ensure_ascii=False) if item["b"] else ''
            rows.append((item["A"], b_json))
        cursor.executemany(sql, rows)
        conn.commit()
        print(f"成功插入 {cursor.rowcount} 条记录")
    finally:
        conn.close()


